/**
 * src/rune/capabilities.ts
 *
 * RUNE Dynamic Capability Registry.
 * Enables runtime synthesis and registration of brand new commands, macros,
 * and native C routines generated by autonomous agents.
 */

export type CustomCommandHandler = (args: string[], input: string) => Promise<string>;

export interface CustomCommand {
  name: string;
  params: string[];
  body: string;
  kind: "rune" | "native";
  compiledBinaryPath?: string;
}

export class CapabilityRegistry {
  private commands = new Map<string, CustomCommand>();
  private handlers = new Map<string, CustomCommandHandler>();

  register(command: CustomCommand): void {
    this.commands.set(command.name.toLowerCase(), command);
  }

  registerHandler(name: string, handler: CustomCommandHandler): void {
    this.handlers.set(name.toLowerCase(), handler);
  }

  get(name: string): CustomCommand | undefined {
    return this.commands.get(name.toLowerCase());
  }

  getHandler(name: string): CustomCommandHandler | undefined {
    return this.handlers.get(name.toLowerCase());
  }

  has(name: string): boolean {
    const k = name.toLowerCase();
    return this.commands.has(k) || this.handlers.has(k);
  }

  list(): string[] {
    return Array.from(new Set([...this.commands.keys(), ...this.handlers.keys()]));
  }
}
